select id, order_id, product_id, quantity, unit_price, avg(unit_price) over (order by quantity, id rows between 6 preceding and 1 preceding) as unit_price_avg_6_prior, lead(quantity, 1) over (partition by product_id order by quantity, id) as next_quantity, ntile(5) over (partition by product_id order by unit_price desc, id) as unit_price_bucket, avg(quantity) over (partition by product_id, order_id) as product_id_avg_quantity, sum(unit_price) over w_ordered as running_unit_price from order_items window w_ordered as (partition by order_id order by quantity, id rows between unbounded preceding and current row)
